const { body, query, validationResult } = require('express-validator');

// Example for future endpoints that accept input
app.get('/users/:id', 
  query('fields').optional().isIn(['name', 'email', 'id']),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
