// Script to check for hardcoded secrets in .env files

const fs = require('fs');
const path = require('path');

// List of sensitive patterns to detect
const sensitivePatterns = [
  /AWS_ACCESS_KEY_ID/i,
  /AWS_SECRET_ACCESS_KEY/i,
  /DATABASE_URL/i,
  /PASSWORD/i,
  /SECRET/i,
  /KEY/i,
  /TOKEN/i,
  /PRIVATE_KEY/i,
  /PASSPHRASE/i
];

// Files to check
const filesToCheck = [
  '.env',
  '.env.test',
  '.env.local',
  '.env.development',
  '.env.production'
];

console.log('🔍 Scanning for hardcoded secrets...\n');

let foundIssues = false;

filesToCheck.forEach(file => {
  try {
    if (fs.existsSync(file)) {
      const content = fs.readFileSync(file, 'utf8');
      const lines = content.split('\n');

      console.log(`📄 Checking ${file}...`);

      lines.forEach((line, index) => {
        // Skip empty lines and comments
        if (!line.trim() || line.trim().startsWith('#')) {
          return;
        }

        sensitivePatterns.forEach(pattern => {
          if (pattern.test(line)) {
            // Check if the value looks like an actual secret (not just a placeholder)
            const valueMatch = line.match(/=(.*)/);
            if (valueMatch) {
              const value = valueMatch[1].trim().replace(/['"]+/g, '');
              // If value doesn't look like a placeholder, flag it
              if (!value.includes('YOUR_') && 
                  !value.includes('your_') && 
                  !value.includes('EXAMPLE') &&
                  !value.includes('example') &&
                  !value.includes('{{') &&
                  value.length > 5) {

                console.log(`  ⚠️  Potential hardcoded secret found in ${file}:${index + 1}`);
                console.log(`     ${line.trim()}`);
                foundIssues = true;
