// Example of secure secrets loading using AWS Secrets Manager
// This is a template for how to securely load secrets

const AWS = require('aws-sdk');
// Alternative: import AWS from 'aws-sdk';

// NEVER hardcode credentials - rely on IAM roles, environment variables, or AWS config files
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'  // Use region from environment
});

/**
 * Load secrets from AWS Secrets Manager
 * @param {string} secretName - The name of the secret in AWS Secrets Manager
 * @returns {Promise<Object>} - The parsed secret values
 */
async function loadSecrets(secretName) {
  try {
    console.log(`⏳ Loading secrets from AWS Secrets Manager: ${secretName}`);

    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
    let secret;

    if (data.SecretString) {
      secret = JSON.parse(data.SecretString);
    } else {
      // For binary secrets (rare)
      const buff = new Buffer(data.SecretBinary, 'base64');
      secret = JSON.parse(buff.toString('ascii'));
    }

    // Set the secrets as environment variables
    Object.keys(secret).forEach(key => {
      process.env[key] = secret[key];
    });

    console.log('✅ Secrets loaded successfully');
    return secret;

  } catch (error) {
    console.error('❌ Failed to load secrets:', error.message);

    // In production, you might want to fail fast
    // But for development, you could fall back to environment variables
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Failed to load required secrets');
    }

    console.warn('⚠️  Running in non-production mode - using environment variables as fallback');
    return {};
  }
}

/**
 * Alternative: Load secrets from environment with validation
 * Use this for development, but never store real secrets in version control
 */
function loadSecretsFromEnv() {
  const requiredSecrets = [
    'DATABASE_URL',
    'JWT_SECRET',
    'SESSION_SECRET'
  ];

  const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);

  if (missingSecrets.length > 0) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error(`Missing required environment variables: ${missingSecrets.join(', ')}`);
    } else {
      console.warn(`⚠️  Missing environment variables: ${missingSecrets.join(', ')}`);
      console.log('   Using default values for development - NEVER use in production!');

      // Set safe defaults for development only
      if (!process.env.DATABASE_URL) {
        process.env.DATABASE_URL = 'postgres://localhost:5432/devdb';
      }
      if (!process.env.JWT_SECRET) {
        process.env.JWT_SECRET = 'dev-jwt-secret-change-in-production';
      }
      if (!process.env.SESSION_SECRET) {
        process.env.SESSION_SECRET = 'dev-session-secret-change-in-production';
      }
    }
  }

  console.log('✅ Environment secrets loaded/validated');
  return requiredSecrets.reduce((acc, secret) => {
    acc[secret] = process.env[secret];
    return acc;
  }, {});
}

/**
 * Main function to load secrets from the appropriate source
 * based on the environment
 */
async function initializeSecrets() {
  console.log(`🚀 Initializing secrets for ${process.env.NODE_ENV || 'development'} environment`);

  if (process.env.NODE_ENV === 'production' || process.env.USE_AWS_SECRETS === 'true') {
    // Production: Use AWS Secrets Manager
    return await loadSecrets(process.env.SECRETS_MANAGER_NAME || 'production/app-secrets');
  } else {
    // Development: Use environment variables (from .env files, but not committed)
    return loadSecretsFromEnv();
  }
}

module.exports = {
  loadSecrets,
  loadSecretsFromEnv,
  initializeSecrets
};

// If this file is run directly, execute the initialization
if (require.main === module) {
  initializeSecrets()
    .then(secrets => {
      console.log('Secrets initialized:', Object.keys(secrets));
    })
    .catch(error => {
      console.error('Failed to initialize secrets:', error);
      process.exit(1);
    });
}

