describe('Security Hardening Tests', () => {
  test('should validate express module integrity', (done) => {
    // This test simulates loading the app with a compromised express module
    const script = `
      // Mock a compromised express module
      const mockExpress = {};
      Object.defineProperty(mockExpress, 'toString', {
        enumerable: false,
        value: () => 'compromised'
      });

      // Replace require to simulate compromised module
      const originalRequire = global.require;
      global.require = function(module) {
        if (module === 'express') {
          return mockExpress;
        }
        return originalRequire(module);
      };

      // Try to load our app - it should fail due to security check
      let exitCode = 0;
      const originalExit = process.exit;
      process.exit = function(code) {
        exitCode = code;
        throw new Error('process.exit called');
      };

      try {
        require('./app.js');
        // If we get here, the security check failed
        process.exit = originalExit;
        console.log('Test failed: App loaded with compromised express module');
        process.exit(1);
      } catch (error) {
        process.exit = originalExit;
        if (error.message === 'process.exit called') {
          // This is expected - the security check worked
          if (exitCode === 1) {
            console.log('Test passed: Security check prevented compromised module');
            process.exit(0);
          } else {
            console.log('Test failed: process.exit called with wrong code');
            process.exit(1);
          }
        } else {
          console.log('Test failed:', error);
          process.exit(1);
        }
      }
    `;

    const child = spawn('node', ['-e', script]);
    let output = '';

    child.stdout.on('data', (data) => {
      output += data;
    });

    child.stderr.on('data', (data) => {
      output += data;
    });

    child.on('close', (code) => {
      if (code === 0 && output.includes('Test passed')) {
        done();
      } else {
        done(new Error(`Test failed: ${output}`));
      }
    });
