const fs = require('fs').promises;
const path = require('path');

// Load .env files safely
async function loadLocalSecrets() {
  const envFiles = [
    '.env',
    `.env.${process.env.NODE_ENV}`,
    '.env.local',
    `.env.${process.env.NODE_ENV}.local`
  ];

  // Don't load any .env files in production
  if (process.env.NODE_ENV === 'production') {
    console.log('Skipping local .env files in production');
    return;
  }

  for (const fileName of envFiles) {
    try {
      const filePath = path.join(process.cwd(), fileName);
      await fs.access(filePath); // Check if file exists

      const content = await fs.readFile(filePath, 'utf8');
      const lines = content.split('\n');

      lines.forEach(line => {
        // Skip comments and empty lines
        if (line.trim() === '' || line.startsWith('#')) return;

        const [key, value] = line.split('=');
        if (key && value) {
          // Don't overwrite existing env vars
          if (!process.env[key.trim()]) {
            process.env[key.trim()] = value.trim().replace(/\n/g, '');
          }
        }
      });

      console.log(`Loaded secrets from ${fileName}`);
    } catch (error) {
      // File doesn't exist - not an error
      if (error.code !== 'ENOENT') {
        console.warn(`Error reading ${fileName}:`, error.message);
      }
    }
  }
}

module.exports = { loadLocalSecrets };

