# Security Review Report: app.js

## Overview
A thorough security review of the provided `app.js` file has been conducted, identifying several critical security vulnerabilities and concerns that require immediate attention.

## 1. Hardcoded Production Secrets in Environment File

**Severity: Critical**

The `.env.test` file contains multiple production credentials and API keys that should never be stored in source code or exposed to applications:

- Production database URL with username and password
- AWS access keys
- Anthropic API key
- Stripe secret key
- Logfire token

**Risk:**
- Complete system compromise
- Data breach of production databases
- Unauthorized access to cloud infrastructure
- Financial loss through Stripe API abuse
- API key monetization by attackers

**Recommendation:**
Remove all production credentials from the environment files immediately. Use proper secret management:

```bash
# Remove the file containing secrets
rm .env.test

# Create a proper .env file with only necessary development variables
echo "PORT=3000" > .env
```

Use environment-specific configuration and secret management:

```javascript
// config.js
require('dotenv').config();

const config = {
  db: {
    url: process.env.DATABASE_URL || 'mongodb://localhost:27017/dev-db'
  },
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
  },
  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY
  }
};

// Validate required production secrets
if (process.env.NODE_ENV === 'production') {
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY'
  ];

  requiredSecrets.forEach(secret => {
    if (!process.env[secret]) {
      throw new Error(`Missing required environment variable: ${secret}`);
    }
  });
}

module.exports = config;
```

## 2. Insecure Express Server Configuration

**Severity: High**

The Express server is created without essential security middleware and best practices.

**Issues Identified:**
- Missing security headers
- No CORS configuration
- No input validation
- No rate limiting
- Default server information exposed

**Recommendation:**
Implement security middleware using `helmet` and `cors`:

```bash
npm install helmet cors express-rate-limit dotenv
```

```javascript
// Updated app.js with security improvements
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const dotenv = require('dotenv');

dotenv.config();

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
  },
  hidePoweredBy: true // Removes X-Powered-By header
}));

// CORS configuration
const allowedOrigins = process.env.NODE_ENV === 'production'
  ? ['https://your-production-domain.com']
  : ['http://localhost:3000', 'http://localhost:3001'];

app.use(cors({
  origin: function(origin, callback) {
    // Allow requests with no origin (mobile apps, curl)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) === -1) {
      const msg = 'The CORS policy for this site does not allow access from the specified origin.';
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});

// Apply rate limiting to all requests
app.use(limiter);

// Set security headers manually if not using helmet
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Input validation middleware
const validateUserParams = (req, res, next) => {
  // Example validation - add more as needed
  if (req.query.id) {
    const id = parseInt(req.query.id);
    if (isNaN(id) || id <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID parameter'
      });
    }
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  // Consider adding authentication for health checks in production
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    env: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with validation
app.get('/users', validateUserParams, (req, res) => {
  try {
    // In a real application, this would query a database
    // Add proper authentication and authorization here

    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users by ID if specified
    if (req.query.id) {
      const id = parseInt(req.query.id);
      const user = mockUsers.find(u => u.id === id);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }
      return res.json(user);
    }

    res.json(mockUsers);
  } catch (error) {
    console.error('Error retrieving users:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, '0.0.0.0', () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;
```

